//! Generated Layer III Huffman tables. DO NOT EDIT.
//!
//! Source: ISO/IEC 11172-3 Table 3-B.7, transcribed by
//! `lab/mp3/gen_mp3_tables.py` from the normative annex text and
//! cross-checked bit-exact against minimp3's decoder tables.
//! `code` is the hcod value right-aligned; `len` is hlen. For the
//! quad tables, `x` packs (v,w,x,y) as v<<3|w<<2|x<<1|y.

/// One entry: `code` over `len` bits decodes to (`x`, `y`).
#[derive(Clone, Copy)]
pub(crate) struct HuffEntry {
    /// Huffman code bits, MSB-first.
    pub code: u32,
    /// Code length.
    pub len: u8,
    /// First value (or packed nibbles for quad tables).
    pub x: u8,
    /// Second value (0 for quad tables).
    pub y: u8,
}

/// A pair table with its `linbits` escape-field width.
#[derive(Clone, Copy)]
pub(crate) struct HuffTable {
    /// Entries sorted by length then code.
    pub entries: &'static [HuffEntry],
    /// Extra bits after a `15` value (ESC).
    pub linbits: u8,
}

